    entry_key bigint NOT NULL,
    value bigint NOT NULL,
    CONSTRAINT lfv4_pk_client_data PRIMARY KEY (id)
);

CREATE TABLE ultimateteam.club_flags (
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    club_id bigint NOT NULL,
    flag text NOT NULL,
    CONSTRAINT lfv4_pk_club_flags PRIMARY KEY (id)
);

CREATE TABLE ultimateteam.club_imports (
    source_sha256 text NOT NULL,
    source_kind text NOT NULL,
    source_path text NOT NULL,
    persona_id bigint NOT NULL,
    summary json NOT NULL,
    imported_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT lfv4_pk_club_imports PRIMARY KEY (source_sha256)
);

CREATE TABLE ultimateteam.legacy_kv (
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    club_id bigint NOT NULL,
    key text NOT NULL,
    value text NOT NULL,
    CONSTRAINT lfv4_pk_legacy_kv PRIMARY KEY (id)
);

CREATE TABLE ultimateteam.schema_migrations (
    version integer NOT NULL,
    applied_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT lfv4_pk_schema_migrations PRIMARY KEY (version)
);
